head.script:
scwin.trigger2_onclick = function(e) {
    var jsonData = [{
            "col1": "가가가",
            "col2": "",
            "col3": "shin"
        },
        {
            "col1": "나나나",
            "col2": "",
            "col3": "shin"
        },
        {
            "col1": "가가가",
            "col2": "",
            "col3": "kim"
        },
        {
            "col1": "다다다",
            "col2": "",
            "col3": "shin"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.grid1_ongroupby = function(options) {
    return false;
};
scwin.onpageload = function() {
}


scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}

scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grd2_column1', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#grd2_column5', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_body_tbody tr').not('.w2grid_hidedRow').length == 4", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd2_column1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_0_2').text() == 'kim'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_1_2').text() == 'shin'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_2_2').text() == 'shin'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_3_2').text() == 'shin'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == 'name3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_closeButtonImg').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd2_column5_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == 'name1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_1_0').text() == '가가가'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_2_0').text() == '가가가'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_5_0').text() == '나나나'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd2_cell_8_0').text() == '다다다'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
